/// The test image is not part of the public repository (AI-generated demo picture); without it the tests skip.
fn image() -> Option<image::RgbImage> {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/two_faces.png");
    if !p.exists() {
        eprintln!("skipped: {} is not available", p.display());
        return None;
    }
    Some(image::open(p).expect("test image").to_rgb8())
}

#[test]
fn raw_outputs_match_onnxruntime() {
    let Some(img) = image() else { return };
    assert_eq!((img.width(), img.height()), (320, 213));
    let out = yunet::raw_outputs(&img).unwrap();
    for (name, len, sum, samples) in OUTPUTS {
        let v = &out[*name].data;
        assert_eq!(v.len(), *len, "{name}");
        let s: f64 = v.iter().map(|x| *x as f64).sum();
        assert!((s - sum).abs() <= 1e-4 * sum.abs().max(1.0) + 1e-3, "{name}: sum {s} vs {sum}");
        for (i, x) in samples.iter() {
            assert!((v[*i] - x).abs() <= 1e-4 * x.abs().max(1.0), "{name}[{i}]: {} vs {x}", v[*i]);
        }
    }
}

#[test]
fn decoded_faces_match_opencv() {
    let Some(img) = image() else { return };
    let found = yunet::detect_at_size(&img).unwrap();
    assert_eq!(found.len(), OPENCV_FACES.len());
    for r in OPENCV_FACES {
        // the same face: nearest box centre
        let (cx, cy) = (r[0] + r[2] / 2.0, r[1] + r[3] / 2.0);
        let g = found.iter().min_by(|a, b| ((a.x + a.b / 2.0 - cx).hypot(a.y + a.h / 2.0 - cy)).total_cmp(&(b.x + b.b / 2.0 - cx).hypot(b.y + b.h / 2.0 - cy))).unwrap();
        for (a, b) in [(g.x, r[0]), (g.y, r[1]), (g.b, r[2]), (g.h, r[3])] {
            assert!((a - b).abs() < 0.05, "box {a} vs {b}");
        }
        assert!((g.confidence - r[14]).abs() < 1e-3, "score {} vs {}", g.confidence, r[14]);
        // landmarks: graineo sorts eyes and mouth corners by image position; OpenCV gives them in the network's order
        let p = g.points.unwrap();
        let mut theirs: Vec<(f32, f32)> = (0..5).map(|i| (r[4 + 2 * i], r[5 + 2 * i])).collect();
        if theirs[0].0 > theirs[1].0 {
            theirs.swap(0, 1);
        }
        if theirs[3].0 > theirs[4].0 {
            theirs.swap(3, 4);
        }
        for (a, b) in p.iter().zip(&theirs) {
            assert!((a.0 - b.0).abs() < 0.05 && (a.1 - b.1).abs() < 0.05, "point {a:?} vs {b:?}");
        }
    }
}

#[test]
fn whole_photo_finds_both_faces() {
    // the two-pass search (coarse + fine) on the small picture finds the same two faces
    let Some(img) = image() else { return };
    let found = yunet::detect(&img).unwrap();
    assert_eq!(found.len(), 2);
}
